package com.toabea.closet.order;
import com.toabea.closet.common.*; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/orders") public class OrderController { private static final Set<String> ALLOWED_STATUSES=Set.of("NEW","PROCESSING","COMPLETED","CANCELLED"); private final OrderService service; private final OrderRepository repo; public OrderController(OrderService s,OrderRepository r){service=s;repo=r;} @PostMapping public ResponseEntity<Order> create(@Valid @RequestBody OrderService.CreateOrderRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(r));} @GetMapping public List<Order> all(){return repo.findAllByOrderByCreatedAtDesc();} @PatchMapping("/{id}/status") public Order status(@PathVariable String id,@RequestParam String value){String next=value.toUpperCase(Locale.ROOT); if(!ALLOWED_STATUSES.contains(next))throw new IllegalArgumentException("Invalid status: "+value); Order o=repo.findById(id).orElseThrow();o.setStatus(next);o.setUpdatedAt(java.time.Instant.now());return repo.save(o);} @PostMapping("/{id}/cancel") public Order cancel(@PathVariable String id){return service.cancelPendingOrder(id);} }
